import { readFileSync } from 'node:fs';

// Sample Abu Dhabi data, generated by scripts/generate-abu-dhabi.js. Swap data/listings.json for a
// real feed (agency CRM, portal partner API...) later - the app only depends on the fields used here.
const readData = (file) => JSON.parse(readFileSync(new URL(`../data/${file}`, import.meta.url), 'utf8'));

export const listings = readData('listings.json');
export const COMMUNITIES = readData('communities.json'); // [{ name, region, freehold, aliases, projects }]
export const LANDMARKS = readData('landmarks.json'); // [{ id, name, kind, aliases, lat, lng }]

export const listingsById = new Map(listings.map((l) => [l.id, l]));
export const landmarksById = new Map(LANDMARKS.map((l) => [l.id, l]));
export const communityByName = new Map(COMMUNITIES.map((c) => [c.name, c]));

export const REGIONS = [...new Set(COMMUNITIES.map((c) => c.region))];
export const TYPES = ['Apartment', 'Penthouse', 'Townhouse', 'Villa'].filter((t) => listings.some((l) => l.type === t));
export const FEATURES = [...new Set(listings.flatMap((l) => l.features))].sort();

export const PRIORITIES = {
  schools: 'Great schools',
  walkability: 'Walkability',
  commute: 'Short commute',
  space: 'More space',
  value: 'Best value',
  yield: 'Rental yield',
  newer: 'Newer build',
  beach: 'Beach & sea',
  quiet: 'Quiet & green',
};

export const COMPLETION = { ready: 'Ready to move in', offplan: 'Off-plan' };
export const PURPOSES = { live: 'To live in', invest: 'Investment' };

// Typical UAE expat mortgage: 20% down (homes under AED 5M), ~4.5%, up to 25 years.
// Shared with the frontend via /api/listings so cards and AI quote the same numbers.
export const LOAN = { downPayment: 0.2, annualRate: 0.045, years: 25 };

// Properties worth AED 2M+ may qualify an investor for a 10-year UAE Golden Visa.
export const GOLDEN_VISA_MIN = 2_000_000;

export const isOffPlan = (l) => l.completion !== 'Ready';

export function monthlyCost(l) {
  const principal = l.price * (1 - LOAN.downPayment);
  const r = LOAN.annualRate / 12;
  const n = LOAN.years * 12;
  return (principal * r) / (1 - (1 + r) ** -n) + (l.serviceCharge || 0) / 12;
}

export function distanceKm(a, b) {
  const rad = Math.PI / 180;
  const dLat = (b.lat - a.lat) * rad;
  const dLng = (b.lng - a.lng) * rad;
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(a.lat * rad) * Math.cos(b.lat * rad) * Math.sin(dLng / 2) ** 2;
  return 6371 * 2 * Math.asin(Math.sqrt(h));
}

// Rough peak-free driving time: roads are ~1.15x the straight line, plus time to get going.
export const driveMinutes = (km) => Math.round(km * 1.15 + 6);

export const aed = (n) => `AED ${Math.round(n).toLocaleString('en-US')}`;
export const bedsLabel = (beds) => (beds === 0 ? 'studio' : `${beds}bd`);

// One compact line per home keeps AI prompts small (the free tier is token-limited).
export function compactListing(l, extra = []) {
  return [
    `[${l.id}] ${l.title} - ${l.type} in ${l.project}, ${l.community}`,
    aed(l.price),
    `${bedsLabel(l.beds)}/${l.baths}ba`,
    `${l.sqft.toLocaleString('en-US')} sqft`,
    isOffPlan(l) ? `off-plan, handover ${l.completion}` : `ready, built ${l.yearBuilt}`,
    l.freehold ? 'freehold (all nationalities)' : 'UAE/GCC nationals only',
    `schools ${l.schoolRating}/10`,
    `walk score ${l.walkScore}`,
    `${l.commuteMinutes} min drive to ${l.commuteTo}`,
    `service charge ${aed(l.serviceCharge)}/yr`,
    `gross yield ${l.rentalYield}%`,
    `est. ${aed(monthlyCost(l))}/mo total`,
    l.features.join(', '),
    ...extra,
  ].join(' | ');
}
